solution.solution.js:
class Rect {
  #width = 1;
  #height = 1;

  constructor(width, height) {
    this.width = width;
    this.height = height;
  }

  static #check(value) {
    if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
      throw new RangeError(`not a positive size: ${value}`);
    }
    return value;
  }

  get width() { return this.#width; }
  set width(value) { this.#width = Rect.#check(value); }
  get height() { return this.#height; }
  set height(value) { this.#height = Rect.#check(value); }
  get area() { return this.#width * this.#height; }
}

unitTests:
test("sizes and area", () => {
  const r = new Rect(3, 4);
  checkEq(r.area, 12);
  r.width = 5;
  checkEq([r.width, r.height, r.area], [5, 4, 20]);
});

test("bad sizes are refused", () => {
  checkThrows(() => new Rect(0, 4), RangeError);
  checkThrows(() => new Rect(3, -1), RangeError);
  checkThrows(() => new Rect("3", 4), RangeError);
  const r = new Rect(2, 2);
  checkThrows(() => { r.height = Infinity; }, RangeError);
  checkEq(r.height, 2);
});

test("area is read-only", () => {
  const descriptor = Object.getOwnPropertyDescriptor(Rect.prototype, "area");
  check(descriptor && typeof descriptor.get === "function" && descriptor.set === undefined, "area should be a getter with no setter");
});

